package it.maurof00.xeonkitpvp.command.admin;

import co.aikar.commands.BaseCommand;
import co.aikar.commands.annotation.CommandAlias;
import co.aikar.commands.annotation.CommandCompletion;
import co.aikar.commands.annotation.CommandPermission;
import co.aikar.commands.annotation.Subcommand;
import it.maurof00.xeonkitpvp.KitPvPCore;
import it.maurof00.xeonkitpvp.model.KitDefinition;
import it.maurof00.xeonkitpvp.model.PlayerProfile;
import it.maurof00.xeonkitpvp.model.QuestDefinition;
import org.bukkit.Bukkit;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

@CommandAlias("kitpvp|kp|kpcore")
@CommandPermission("kitpvp.admin")
public final class AdminCommand extends BaseCommand {
    private final KitPvPCore plugin; public AdminCommand(KitPvPCore plugin){this.plugin=plugin;}
    @Subcommand("admin help") public void help(CommandSender sender){sender.sendMessage(plugin.getMessages().prefix()+"&b&lXeonKitPvP Admin");sender.sendMessage("&f/kitpvp admin money <set|give|take> <player> <amount>");sender.sendMessage("&f/kitpvp admin stats <set|add|reset> <player> <stat> [value]");sender.sendMessage("&f/kitpvp admin prestige <set|add|reset> <player> [value]");sender.sendMessage("&f/kitpvp admin kit <give|take> <player> <kit>");sender.sendMessage("&f/kitpvp admin cosmetic <tag|effect> <give> <player> <id>");sender.sendMessage("&f/kitpvp admin quest <reset|complete> <player> <daily|weekly> <id>");sender.sendMessage("&f/kitpvp admin antifarm clear");sender.sendMessage("&f/kitpvp admin combat clear <player>");sender.sendMessage("&f/kitpvp admin player reset <player>");sender.sendMessage("&f/kitpvp admin arena <add|remove|list> [world]");sender.sendMessage("&f/kitpvp admin heal <player> | feed <player> | clear <player>");sender.sendMessage("&f/kitpvp debug");}
    @Subcommand("admin money set") @CommandCompletion("@players") public void moneySet(CommandSender s,String n,long a){money(s,n,a,"set");}
    @Subcommand("admin money give") @CommandCompletion("@players") public void moneyGive(CommandSender s,String n,long a){money(s,n,a,"give");}
    @Subcommand("admin money take") @CommandCompletion("@players") public void moneyTake(CommandSender s,String n,long a){money(s,n,a,"take");}
    private void money(CommandSender s,String n,long a,String mode){PlayerProfile p=plugin.getPlayers().getByName(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}a=Math.max(0L,a);if("set".equals(mode))p.setCoins(a);else if("give".equals(mode))p.addCoins(a);else p.setCoins(Math.max(0L,p.getCoins()-a));plugin.getPlayers().saveProfile(p);plugin.getMessages().send(s,"admin."+("set".equals(mode)?"money-set":"money-"+mode),map("player",p.getLastName(),"amount",String.valueOf(a)));}
    @Subcommand("admin stats set") @CommandCompletion("@players kills|deaths|coins|xp|level|prestige|streak|beststreak|bounty") public void statsSet(CommandSender s,String n,String stat,long value){stats(s,n,stat,value,false);}
    @Subcommand("admin stats add") @CommandCompletion("@players kills|deaths|coins|xp|level|prestige|streak|beststreak|bounty") public void statsAdd(CommandSender s,String n,String stat,long value){stats(s,n,stat,value,true);}
    @Subcommand("admin stats reset") @CommandCompletion("@players kills|deaths|coins|xp|level|prestige|streak|beststreak|bounty") public void statsReset(CommandSender s,String n,String stat){stats(s,n,stat,0L,false);}
    private void stats(CommandSender s,String n,String stat,long value,boolean add){PlayerProfile p=plugin.getPlayers().getByName(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}try{long current=plugin.getPlayers().getStat(p,stat);plugin.getPlayers().setStat(p,stat,add?current+value:value);plugin.getPlayers().saveProfile(p);plugin.getMessages().send(s,"admin.stat-"+(add?"add":"set"),map3("player",p.getLastName(),"stat",stat,"value",String.valueOf(plugin.getPlayers().getStat(p,stat))));}catch(IllegalArgumentException ex){s.sendMessage(plugin.getMessages().prefix()+"&cStatistiche valide: kills, deaths, coins, xp, level, prestige, streak, beststreak, bounty");}}
    @Subcommand("admin prestige set") @CommandCompletion("@players") public void prestigeSet(CommandSender s,String n,int value){prestige(s,n,value,false);}
    @Subcommand("admin prestige add") @CommandCompletion("@players") public void prestigeAdd(CommandSender s,String n,int value){prestige(s,n,value,true);}
    @Subcommand("admin prestige reset") @CommandCompletion("@players") public void prestigeReset(CommandSender s,String n){prestige(s,n,0,false);}
    private void prestige(CommandSender s,String n,int value,boolean add){PlayerProfile p=plugin.getPlayers().getByName(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}int next=add?p.getPrestige()+value:value;p.setPrestige(Math.max(0,Math.min(plugin.getPluginConfig().maxPrestige(),next)));plugin.getPlayers().saveProfile(p);plugin.getMessages().send(s,"admin.prestige-"+(add?"add":"set"),map("player",p.getLastName(),"value",String.valueOf(p.getPrestige())));}
    @Subcommand("admin kit give") @CommandCompletion("@players @kits") public void kitGive(CommandSender s,String n,String k){kit(s,n,k,true);}
    @Subcommand("admin kit take") @CommandCompletion("@players @kits") public void kitTake(CommandSender s,String n,String k){kit(s,n,k,false);}
    private void kit(CommandSender s,String n,String k,boolean give){PlayerProfile p=plugin.getPlayers().getByName(n);KitDefinition kit=plugin.getKits().get(k);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}if(kit==null){plugin.getMessages().send(s,"kit-not-found",java.util.Collections.singletonMap("kit",k));return;}if(give)p.getOwnedKits().add(kit.getId());else{p.getOwnedKits().remove(kit.getId());if("warrior".equals(kit.getId()))p.getOwnedKits().add("warrior");}plugin.getPlayers().saveProfile(p);plugin.getMessages().send(s,"admin.kit-"+(give?"give":"take"),java.util.Collections.singletonMap("kit",kit.getId()));}
    @Subcommand("admin cosmetic tag give") @CommandCompletion("@players @tags") public void tagGive(CommandSender s,String n,String id){PlayerProfile p=plugin.getPlayers().getByName(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}if(!plugin.getTags().unlock(p,id)){plugin.getMessages().send(s,"shop.invalid");return;}plugin.getPlayers().saveProfile(p);plugin.getMessages().send(s,"admin.tag-give",map("player",p.getLastName(),"tag",id));}
    @Subcommand("admin cosmetic effect give") @CommandCompletion("@players @killeffects") public void effectGive(CommandSender s,String n,String id){PlayerProfile p=plugin.getPlayers().getByName(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}if(!plugin.getKillEffects().unlock(p,id)){plugin.getMessages().send(s,"shop.invalid");return;}plugin.getPlayers().saveProfile(p);plugin.getMessages().send(s,"admin.effect-give",map("player",p.getLastName(),"effect",id));}
    @Subcommand("admin quest reset") @CommandCompletion("@players") public void questReset(CommandSender s,String n){PlayerProfile p=plugin.getPlayers().getByName(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}plugin.getQuests().reset(p);plugin.getPlayers().saveProfile(p);plugin.getMessages().send(s,"quest.reset",java.util.Collections.singletonMap("player",p.getLastName()));}
    @Subcommand("admin quest complete") @CommandCompletion("@players daily|weekly") public void questComplete(CommandSender s,String n,String period,String id){PlayerProfile p=plugin.getPlayers().getByName(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}QuestDefinition.Period qperiod="weekly".equalsIgnoreCase(period)?QuestDefinition.Period.WEEKLY:QuestDefinition.Period.DAILY;if(!plugin.getQuests().markComplete(p,id,qperiod)){plugin.getMessages().send(s,"shop.invalid");return;}plugin.getPlayers().saveProfile(p);plugin.getMessages().send(s,"admin.quest-completed",map("player",p.getLastName(),"quest",id));}
    @Subcommand("admin antifarm clear") public void antiFarmClear(CommandSender s){plugin.getAntiFarm().clear();plugin.getMessages().send(s,"admin.anti-farm-cleared");}
    @Subcommand("admin combat clear") @CommandCompletion("@players") public void combatClear(CommandSender s,String n){Player p=Bukkit.getPlayerExact(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}plugin.getCombat().clearQuiet(p);plugin.getMessages().send(s,"admin.combat-cleared",java.util.Collections.singletonMap("player",p.getName()));}
    @Subcommand("admin player reset") @CommandCompletion("@players") public void reset(CommandSender s,String n){PlayerProfile p=plugin.getPlayers().getByName(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}p.setKills(0);p.setDeaths(0);p.setCoins(plugin.getPluginConfig().joinCoins());p.setXp(0);p.setLevel(1);p.setPrestige(0);p.setStreak(0);p.setBestStreak(0);p.setBounty(0);p.setSelectedKit("warrior");p.setSelectedTag("default");p.setSelectedKillEffect("none");p.getOwnedKits().clear();p.getOwnedKits().add("warrior");p.getOwnedTags().clear();p.getOwnedTags().add("default");p.getOwnedKillEffects().clear();p.getOwnedKillEffects().add("none");plugin.getQuests().reset(p);plugin.getPlayers().saveProfile(p);plugin.getMessages().send(s,"admin.player-reset",java.util.Collections.singletonMap("player",p.getLastName()));}
    @Subcommand("admin arena add") public void arenaAdd(CommandSender s,String world){modifyArena(s,world,true);}
    @Subcommand("admin arena remove") public void arenaRemove(CommandSender s,String world){modifyArena(s,world,false);}
    @Subcommand("admin arena list") public void arenaList(CommandSender s){plugin.getMessages().send(s,"admin.arena-list",java.util.Collections.singletonMap("worlds",String.join(", ",plugin.getPluginConfig().enabledWorlds())));}
    private void modifyArena(CommandSender s,String world,boolean add){List<String> worlds=new ArrayList<String>(plugin.getPluginConfig().enabledWorlds());if(add){if(!worlds.contains(world))worlds.add(world);}else if(!worlds.remove(world)){plugin.getMessages().send(s,"admin.arena-not-found",java.util.Collections.singletonMap("world",world));return;}plugin.getConfig().set("game.enabled-worlds",worlds);plugin.saveConfig();plugin.getMessages().send(s,"admin.arena-"+(add?"added":"removed"),java.util.Collections.singletonMap("world",world));}
    @Subcommand("admin heal") @CommandCompletion("@players") public void heal(CommandSender s,String n){Player p=player(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}p.setHealth(p.getMaxHealth());}
    @Subcommand("admin feed") @CommandCompletion("@players") public void feed(CommandSender s,String n){Player p=player(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}p.setFoodLevel(20);p.setSaturation(20F);}
    @Subcommand("admin clear") @CommandCompletion("@players") public void clear(CommandSender s,String n){Player p=player(n);if(p==null){plugin.getMessages().send(s,"player-not-found");return;}p.getInventory().clear();p.getInventory().setArmorContents(new org.bukkit.inventory.ItemStack[4]);}
    @Subcommand("debug") public void debug(CommandSender s){s.sendMessage(plugin.getMessages().prefix()+plugin.getMessages().get("admin.debug-header"));s.sendMessage("&7Version: &f"+plugin.getDescription().getVersion());s.sendMessage("&7Server: &f"+Bukkit.getVersion());s.sendMessage("&7Java: &f"+System.getProperty("java.version"));s.sendMessage("&7Kits: &f"+plugin.getKits().size());s.sendMessage("&7Players cached: &f"+plugin.getPlayers().allProfiles().size());s.sendMessage("&7Quests: &f"+plugin.getQuests().all().size());s.sendMessage("&7Tags: &f"+plugin.getTags().ids().size());s.sendMessage("&7Kill Effects: &f"+plugin.getKillEffects().ids().size());s.sendMessage("&7AntiFarm tracked pairs: &f"+plugin.getAntiFarm().trackedPairs());s.sendMessage("&7Vault: &f"+(plugin.getHooks().getVault()!=null&&plugin.getHooks().getVault().isAvailable()));s.sendMessage("&7PlaceholderAPI: &f"+(plugin.getHooks().getPlaceholder()!=null));s.sendMessage("&7TAB API: &f"+(plugin.getHooks().getTab()!=null&&plugin.getHooks().getTab().isAvailable()));s.sendMessage("&7ACF: &f0.5.1-SNAPSHOT (shaded)");}
    private Player player(String n){return Bukkit.getPlayerExact(n);}
    private Map<String,String> map(String a,String av,String b,String bv){Map<String,String>m=new HashMap<String,String>();m.put(a,av);m.put(b,bv);return m;}
    private Map<String,String> map3(String a,String av,String b,String bv,String c,String cv){Map<String,String>m=map(a,av,b,bv);m.put(c,cv);return m;}
}
